    {
      "card_ids": ["C12"],
      "claim": "In healthy adult volunteers, Me4FDG did not cross the BBB, providing contradictory evidence that some similar tracers lack meaningful CNS access.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "low",
  "decision_summary": "Predicted pass: the most direct systemic CNS-access evidence among retrieved analogues is predominantly positive, including oral brain uptake, BBB transport, and CSF penetration. Negative records are fewer and involve disrupted-barrier, efflux-inhibited, or less transferable conditions, but low Morgan similarities reduce confidence.",
